{
  "states": [
    "LISTEN",
    "RESPOND",
    "REQUEST",
    "PARTOPEN",
    "OPEN",
    "TIMEWAIT",
    "CLOSING"
  ],
  "transitions": [
    {
      "from": "LISTEN",
      "event": "P.type == Request or P contains a valid Init Cookie option",
      "action": "Set S := new socket for this port pair; S.state = RESPOND; Choose S.ISS; Initialize S.GAR := S.ISS; Set S.ISR, S.GSR, S.SWL, S.SWH from packet or Init Cookies",
      "to": "RESPOND"
    },
    {
      "from": "REQUEST",
      "event": "P.type == Response and S.AWL <= P.ackno <= S.AWH",
      "action": "Set S.GSR, S.ISR, S.SWL, S.SWH; S.state := PARTOPEN; Set PARTOPEN timer",
      "to": "PARTOPEN"
    },
    {
      "from": "REQUEST",
      "event": "P.type == Reset and S.AWL <= P.ackno <= S.AWH",
      "action": "Set S.GSR, S.ISR, S.SWL, S.SWH; Tear down connection; S.state := TIMEWAIT; Set TIMEWAIT timer",
      "to": "TIMEWAIT"
    },
    {
      "from": "RESPOND",
      "event": "P.type == Request",
      "action": "Send Response, possibly containing Init Cookie; If Init Cookie was sent, Destroy S",
      "to": "RESPOND"
    },
    {
      "from": "RESPOND",
      "event": "P.type != Request",
      "action": "S.OSR := P.seqno; S.state := OPEN",
      "to": "OPEN"
    },
    {
      "from": "PARTOPEN",
      "event": "P.type == Response",
      "action": "Send Ack",
      "to": "PARTOPEN"
    },
    {
      "from": "PARTOPEN",
      "event": "P.type != Sync and P.type != Response",
      "action": "S.OSR := P.seqno; S.state := OPEN",
      "to": "OPEN"
    },
    {
      "from": "CLOSING",
      "event": "P.type == CloseReq and S.state < CLOSEREQ",
      "action": "Generate Close; S.state := CLOSING; Set CLOSING timer",
      "to": "CLOSING"
    },
    {
      "from": "OPEN",
      "event": "P.type == Reset",
      "action": "Tear down connection; S.state := TIMEWAIT; Set TIMEWAIT timer",
      "to": "TIMEWAIT"
    }
  ]
}

